Усі три офіційні SDK доступні на одному рівні. Показується лише обрана вкладка, щоб ви виконали один шлях без прокручування двох інших програм. PHP Python Rust Вимоги: PHP 8.1 або новіший і Composer. Використовується незалежний від фреймворку пакет durable-workflow/sdk, а не вбудований рушій Laravel. Встановіть SDK. mkdir durable-workflow-php-quickstart cd durable-workflow-php-quickstart composer require durable-workflow/sdk:3.2.0 Додайте worker і клієнт. Розгорніть повний код і скопіюйте обидва файли в новий проєкт. Повний виконуваний код PHP Worker реєструє один тип workflow та один тип activity у власній черзі завдань. cat > worker.php <<'PHP' <?php declare(strict_types=1); require __DIR__.'/vendor/autoload.php'; use DurableWorkflow\Client; use DurableWorkflow\Worker; use DurableWorkflow\Worker\ActivityContext; use DurableWorkflow\Worker\WorkflowContext; $client = new Client('http://localhost:8080', token: 'dev-token'); $worker = new Worker($client, 'quickstart-php'); $worker->registerActivity( 'quickstart.greet', static fn (ActivityContext $context, string $name): string => "Hello, {$name}!", ); $worker->registerWorkflow( 'quickstart.greeter', static function (WorkflowContext $context, string $name): array { $greeting = $context->activity('quickstart.greet', [$name]); return ['greeting' => $greeting, 'language' => 'php']; }, ); $worker->run(); PHP Клієнт і читання результату​ Цей клієнт запускає workflow з унікальною назвою, очікує його обраний run і потім описує стійкий термінальний стан, збережений Server. cat > start.php <<'PHP' <?php declare(strict_types=1); require __DIR__.'/vendor/autoload.php'; use DurableWorkflow\Client; $client = new Client('http://localhost:8080', token: 'dev-token'); $workflowId = 'quickstart-php-greeter-'.bin2hex(random_bytes(4)); $handle = $client->startWorkflow( workflowType: 'quickstart.greeter', workflowId: $workflowId, taskQueue: 'quickstart-php', input: ['PHP'], ); $result = $handle->result(timeoutSeconds: 30); $execution = $handle->describeSelectedRun(); echo "workflow_id={$execution->workflowId}
"; echo "status={$execution->status}
"; echo 'result='.json_encode($result, JSON_THROW_ON_ERROR)."
"; PHP Запустіть worker і клієнт. php worker.php > quickstart-worker.log 2>&1 & export QUICKSTART_WORKER_PID=$! trap 'kill "$QUICKSTART_WORKER_PID" 2>/dev/null || true' EXIT php start.php kill "$QUICKSTART_WORKER_PID" 2>/dev/null || true trap - EXIT Очікуваний результат: status=completed і результат із "greeting":"Hello, PHP!". Ви запустили окремий worker PHP та переглянули його стійкий результат без Laravel. Продовжіть із посібником PHP SDK. Вимоги: Python 3.10 або новіший. Програма містить worker і клієнт в одному процесі, але вони спілкуються із Server через публічні API worker та площини керування. Встановіть SDK. Використовуйте стабільний випуск Python SDK із маніфесту вище. Згенерована точна вимога зберігає цей виконуваний шлях на задокументованій стабільній лінійці випуску. mkdir durable-workflow-python-quickstart cd durable-workflow-python-quickstart python3 -m venv .venv . .venv/bin/activate pip install durable-workflow==2.8.0 Створіть і запустіть worker та клієнт. Розгорніть повну програму. Її остання команда запускає виконання. Повний виконуваний код Python cat > greeter.py <<'PY' import asyncio import time from durable_workflow import Client, Worker, activity, workflow @activity.defn(name="quickstart.greet") async def greet(name: str) -> dict: return {"greeting": f"Hello, {name}!", "language": "python"} @workflow.defn(name="quickstart.greeter") class GreeterWorkflow: def run(self, ctx, name): return (yield ctx.schedule_activity("quickstart.greet", [name])) async def main(): workflow_id = f"quickstart-python-greeter-{int(time.time())}" async with Client( "http://localhost:8080", token="dev-token", namespace="default", ) as client: handle = await client.start_workflow( workflow_type="quickstart.greeter", task_queue="quickstart-python", workflow_id=workflow_id, input=["Python"], ) worker = Worker( client, task_queue="quickstart-python", workflows=[GreeterWorkflow], activities=[greet], ) await worker.run_until(workflow_id=workflow_id, timeout=30.0) result = await handle.result(timeout=10.0) execution = await handle.describe_run() print(f"workflow_id={execution.workflow_id}") print(f"status={execution.status}") print(f"result={result}") asyncio.run(main()) PY python greeter.py Очікуваний результат: status=completed і результат із Hello, Python!. Останні два виклики SDK читають результат обраного run та стійкий термінальний стан із Server. Продовжіть із посібником Python SDK. Вимоги: Rust 1.86 або новіший. Приклад запускає власний worker і клієнт в одному процесі Tokio. Встановіть SDK. cargo new durable-workflow-rust-quickstart cd durable-workflow-rust-quickstart cargo add durable-workflow@=4.2.0 cargo add tokio --features macros,rt-multi-thread,time Створіть і запустіть worker та клієнт. Розгорніть повну програму. Її остання команда компілює та запускає виконання. Повний виконуваний код Rust cat > src/main.rs <<'RS' use std::time::{Duration, SystemTime, UNIX_EPOCH}; use durable_workflow::{json, Client, Result, Worker, WorkflowResultOptions}; #[tokio::main] async fn main() -> Result<()> { let client = Client::builder("http://localhost:8080") .token(Some("dev-token".to_string())) .namespace("default") .build()?; let task_queue = "quickstart-rust"; let mut worker = Worker::new(client.clone(), task_queue); worker.register_activity("quickstart.greet", |_context, arguments| async move { let name = arguments .get(0) .and_then(|value| value.as_str()) .unwrap_or("Rust"); Ok(json!({"greeting": format!("Hello, {name}!"), "language": "rust"})) }); worker.register_workflow("quickstart.greeter", |context, input| async move { let name = input.get(0).and_then(|value| value.as_str()).unwrap_or("Rust"); context.activity("quickstart.greet", json!([name])).await }); worker.register().await?; let workflow_id = format!("quickstart-rust-greeter-{}", unique_suffix()); let handle = client .start_workflow( "quickstart.greeter", task_queue, &workflow_id, json!(["Rust"]), ) .await?; let watcher = handle.clone(); worker .run_until(async move { loop { if watcher.describe().await.is_ok_and(|run| run.is_terminal()) { break; } tokio::time::sleep(Duration::from_millis(500)).await; } }) .await?; let result = handle.result(WorkflowResultOptions::default()).await?; let execution = handle.describe_selected_run().await?; println!("workflow_id={workflow_id}"); println!("status={}", execution.status.as_deref().unwrap_or("unknown")); println!("result={result}"); Ok(()) } fn unique_suffix() -> u128 { SystemTime::now() .duration_since(UNIX_EPOCH) .unwrap_or_default() .as_millis() } RS cargo run Очікуваний результат: status=completed і результат JSON із "greeting":"Hello, Rust!". Приклад очікує завершення run своїм worker, потім читає стійкий статус і декодований результат обраного run. Продовжіть із посібником Rust SDK.
